    SaldoKurangException(int kurang) {
        super("Saldo kurang " + kurang);
    }
}

public class Main {
    static void bayar(int saldo, int belanja) {
        if (belanja > saldo) {
            throw new SaldoKurangException(belanja - saldo);
        }
        System.out.println("Lunas");
    }

    public static void main(String[] args) {
        int stokKopi = 0;
        try {
            if (stokKopi == 0) {
                throw new StokHabisException("Kopi");
            }
        } catch (StokHabisException e) {
            System.out.println(e.getMessage());
        }

        int saldo = 10000;
        int belanja = 15000;
        try {
            if (belanja > saldo) {
                throw new SaldoKurangException(belanja - saldo);
            }
        } catch (SaldoKurangException e) {
            System.out.println(e.getMessage());
        }
        bayar(20000, 15000);
    }
}

class StokHabisException extends RuntimeException {
    StokHabisException(String barang) {
        super(barang + " habis");
    }
}

class SaldoKurangException extends RuntimeException {
    SaldoKurangException(int kurang) {
        super("Saldo kurang " + kurang);
    }
}

