public class Main {
    public static void main(String[] args) {
        try {
            simpan("");
        } catch (DataKosongException e) {
            System.out.println(e.getMessage());
        }
    }

    static void simpan(String nama) {
        if (nama.isEmpty()) {
            throw new DataKosongException("Nama wajib diisi");
        }
    }
}

class DataKosongException extends RuntimeException {
    DataKosongException(String pesan) {
        super(pesan);
    }
}
